-- DB-06: durable storage-class and JavaScript-safe-range guards for authoritative business integers.
-- Sign and zero semantics remain in services; these triggers only enforce the shared integer-domain invariant.
-- Existing rows are scanned first. Migration aborts without modifying data if a violation exists.
CREATE TEMP TABLE "db06_integer_migration_guard" ("invalid" INTEGER NOT NULL);
--> statement-breakpoint
CREATE TEMP TRIGGER "db06_integer_migration_guard_reject" BEFORE INSERT ON "db06_integer_migration_guard" BEGIN SELECT RAISE(ABORT, 'DB-06 historical integer-domain violation'); END;
